"""Markov-chain (order-2 character) fantasy name generator."""

import random

CORPUS = [
    "Aldric", "Branwen", "Cedric", "Doriath", "Elowen", "Faelan",
    "Gwyneth", "Halvard", "Isolde", "Jorund", "Kaelith", "Lorien",
    "Morwen", "Nimueh", "Orin", "Peregrin", "Quillon", "Rhiannon",
    "Sorrel", "Theodric",
]

START, END = "^", "$"


def build_model(corpus=CORPUS):
    """Order-2 char model: map 2-char context -> list of next chars.

    Contexts include the start sentinel; END is a possible 'next' token.
    """
    model = {}
    for name in corpus:
        seq = START + START + name + END
        for i in range(len(seq) - 2):
            ctx = seq[i : i + 2]
            model.setdefault(ctx, []).append(seq[i + 2])
    return model


def generate(model, rng):
    """Sample one name from the model."""
    ctx = START + START
    out = []
    while True:
        nxt = rng.choice(model[ctx])
        if nxt == END:
            return "".join(out)
        if len(out) >= 12:  # hard stop to avoid runaway generation
            return "".join(out)
        out.append(nxt)
        ctx = out[-2] + out[-1]


def generate_name(rng, model=None, min_len=4, max_len=12,
                  corpus=CORPUS, max_attempts=100):
    """Generate a valid name, rejecting bad lengths and corpus copies."""
    if model is None:
        model = build_model(corpus)
    corpus_set = set(corpus)
    for _ in range(max_attempts):
        name = generate(model, rng)
        if min_len <= len(name) <= max_len and name not in corpus_set:
            return name
    raise RuntimeError("failed to generate a valid name within attempt cap")


if __name__ == "__main__":
    rng = random.Random(9)
    print([generate_name(rng) for _ in range(5)])

