import random
import re

from namegen import CORPUS, START, END, build_model, generate_name


def _names_for_seed(seed=9, n=50):
    rng = random.Random(seed)
    return [generate_name(rng) for _ in range(n)]


def test_deterministic_across_runs():
    assert _names_for_seed() == _names_for_seed()


def test_trigrams_exist_in_model():
    model = build_model()
    # every emitted transition (context -> next) must exist in training data
    transitions = {(ctx, nxt) for ctx, nexts in model.items() for nxt in nexts}
    for name in _names_for_seed():
        seq = START + START + name + END
        for i in range(len(seq) - 2):
            assert (seq[i : i + 2], seq[i + 2]) in transitions


def test_length_bounds():
    for name in _names_for_seed():
        assert 4 <= len(name) <= 12


def test_no_exact_corpus_copies():
    corpus_set = set(CORPUS)
    for name in _names_for_seed():
        assert name not in corpus_set


def test_uniqueness_at_least_30():
    assert len(set(_names_for_seed())) >= 30

